import{_ as i,o as a,c as l,ai as e}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"内容生产流水线搭建","description":"","frontmatter":{},"headers":[],"relativePath":"ai/creation/content-pipeline.md","filePath":"ai/creation/content-pipeline.md"}'),r={name:"ai/creation/content-pipeline.md"};function n(o,t,s,d,h,c){return a(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="内容生产流水线搭建" tabindex="-1">内容生产流水线搭建 <a class="header-anchor" href="#内容生产流水线搭建" aria-label="Permalink to “内容生产流水线搭建”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>做内容久了会发现，真正的瓶颈不是&quot;写不出来&quot;，而是<strong>每次都从零启动</strong>：</p><ul><li>选题靠当天灵光一现，想到哪写到哪，常写的领域写枯了，手边明明有一堆素材却从没整理过；</li><li>一篇稿子的生产过程散落各处：想法在备忘录、素材在下载文件夹、草稿在云端文档、发布后就再也找不到；</li><li>从选题到发布全靠一次性的意志力，每个环节都要重新进入状态，一篇文章拖两周是常态；</li><li>AI 用得到处都是：让它生成选题、生成初稿、生成标题，但各环节互相打架，产出的东西质量不稳定，返工反而更多。</li></ul><p>对照软件工程就很清楚：这是<strong>没有 CI/CD 的手工发布</strong>。写内容和做软件一样，单点靠灵感，规模化靠流水线。流水线的意义是把&quot;每篇都要想一遍的过程&quot;固化下来，让大脑只花在真正需要创造力的环节。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-五段式流水线-选题库-→-素材-→-草稿-→-发布-→-分发" tabindex="-1">1. 五段式流水线：选题库 → 素材 → 草稿 → 发布 → 分发 <a class="header-anchor" href="#_1-五段式流水线-选题库-→-素材-→-草稿-→-发布-→-分发" aria-label="Permalink to “1. 五段式流水线：选题库 → 素材 → 草稿 → 发布 → 分发”">​</a></h3><p>整条链路五个阶段，每段有明确的输入、输出和 AI 角色：</p><table tabindex="0"><thead><tr><th>阶段</th><th>输入</th><th>输出</th><th>人做什么</th><th>AI 做什么</th></tr></thead><tbody><tr><td>选题</td><td>选题库、热点、工作记录</td><td>本期确定的 1-2 个选题</td><td>判断价值和优先级</td><td>发散候选、查热度与竞争</td></tr><tr><td>素材</td><td>选题</td><td>素材包（案例/数据/引用）</td><td>提供真实案例和观点</td><td>搜集背景、整理提纲</td></tr><tr><td>草稿</td><td>素材包</td><td>完整初稿</td><td>写核心结论与个人部分</td><td>组织成文、润色</td></tr><tr><td>发布</td><td>初稿</td><td>各平台成稿</td><td>终审、事实核查</td><td>适配各平台格式</td></tr><tr><td>分发</td><td>成稿</td><td>多平台内容 + 台账</td><td>定节奏、看数据</td><td>拆形态、批量改写</td></tr></tbody></table><p>两个设计原则：</p><ul><li><strong>AI 擅长&quot;生成候选&quot;，人擅长&quot;做判断&quot;</strong>：每个环节让 AI 出 3 个选项，人从选项里挑，而不是让人从空白开始想、也不是让 AI 从一句话直接定稿；</li><li><strong>上一段的输出是下一段的输入</strong>：素材包没凑齐不进草稿阶段，草稿没过核查不进发布——阶段门槛防止&quot;带着半成品往下漂流&quot;。</li></ul><h3 id="_2-选题库-流水线的原料仓" tabindex="-1">2. 选题库：流水线的原料仓 <a class="header-anchor" href="#_2-选题库-流水线的原料仓" aria-label="Permalink to “2. 选题库：流水线的原料仓”">​</a></h3><p>选题库是整条线的起点，也是最容易被忽视的一环。用一个简单的表维护（Notion / 飞书表格均可）：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>| 选题 | 来源 | 目标栏目 | 形态（长文/短串/清单）| 状态 | 预估难度 |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>来源标记</strong>三种：工作中的真实问题（质量最高）、读者/同行提问、热点借势；</li><li>随手记：每次刷到好问题、自己踩了坑，10 秒钟记一行，<strong>录入成本必须低于 15 秒</strong>，否则坚持不了；</li><li>每周选题会（15 分钟）：从库里挑 1-2 个进本周生产，标注状态流转（待写→生产中→已发）；</li><li>目标是库存常年 ≥ 20 条，<strong>选题库见底 = 断更的前兆</strong>。</li></ul><h3 id="_3-模板与-checklist-把经验固化成文件" tabindex="-1">3. 模板与 Checklist：把经验固化成文件 <a class="header-anchor" href="#_3-模板与-checklist-把经验固化成文件" aria-label="Permalink to “3. 模板与 Checklist：把经验固化成文件”">​</a></h3><p>流水线的稳定性靠两类固化资产：</p><p><strong>模板（让每篇的起步成本趋近于零）</strong></p><ul><li>文章模板：固定的 H2 骨架（场景与问题 / 做法 / 关键要点 / 小结）——读者熟悉，写作者不用每次排结构；</li><li>标题模板：3-5 个验证过的标题结构（&quot;如何……&quot;、&quot;我用 X 做了 Y&quot;、&quot;……的 N 个坑&quot;）；</li><li>提示词模板：给 AI 的系统提示（定位、读者、语气、禁用套话）存成固定文本，每次只换选题和素材。</li></ul><p><strong>Checklist（防止质量事故）</strong></p><ul><li>发布前 Checklist：事实核查项（版本/命令/数据）、错别字、封面图、内外链、平台格式；</li><li>分发 Checklist：每个平台的形态改动、台账登记、发布时间。</li></ul><p>模板管&quot;不从零开始&quot;，Checklist 管&quot;不出低级错&quot;。两者都是 Markdown 文件放进仓库（或笔记工具），随做随改——<strong>清单也是代码，要维护</strong>。</p><h3 id="_4-各环节-ai-角色的边界" tabindex="-1">4. 各环节 AI 角色的边界 <a class="header-anchor" href="#_4-各环节-ai-角色的边界" aria-label="Permalink to “4. 各环节 AI 角色的边界”">​</a></h3><p>流水线里 AI 出现四次，角色各不相同，混用就会翻车：</p><ul><li><strong>选题环节：头脑风暴员</strong>——给候选和角度，但&quot;发散在前、收敛在后&quot;，选题判断权在人；</li><li><strong>素材环节：资料员</strong>——搜集背景、列提纲、补盲点；涉及事实的部分标记来源，人工复核；</li><li><strong>草稿环节：执笔者</strong>——按人给的素材包和观点成文；核心论点、案例、结论必须人提供；</li><li><strong>发布/分发环节：排版工与改写工</strong>——平台适配、批量拆改，这类机械劳动交给它性价比最高。</li></ul><p>关键认知：<strong>AI 放大的是你流水线的成熟度</strong>。流程清晰时它是倍增器；流程混乱时它只是把混乱加速。所以先把人工流程跑通 3-5 篇，再逐段引入 AI，不要一上来全自动化。</p><h3 id="_5-落地-先跑最小流水线" tabindex="-1">5. 落地：先跑最小流水线 <a class="header-anchor" href="#_5-落地-先跑最小流水线" aria-label="Permalink to “5. 落地：先跑最小流水线”">​</a></h3><p>不需要一次建全套，按这个顺序搭：</p><ol><li>第 1 周：只建选题库 + 文章模板，手工跑一篇；</li><li>第 2-3 周：加发布 Checklist，把提示词模板固化；</li><li>第 4 周起：引入分发环节（一稿多发流程），建分发台账；</li><li>每 10 篇做一次流程复盘：哪个环节最耗时、哪类返工最多，改对应环节——<strong>流水线自己也要迭代</strong>。</li></ol><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>内容生产 = 五段流水线（选题→素材→草稿→发布→分发），上段输出是下段输入，阶段门槛防半成品漂移；</li><li>选题库是原料仓：录入低于 15 秒、库存常 ≥20 条、每周 15 分钟选题会，见底即断更前兆；</li><li>两类固化资产：模板管起步（文章/标题/提示词模板），Checklist 管底线（发布/分发核查）；</li><li>AI 四次出场角色固定：头脑风暴员、资料员、执笔者、改写工——发散与判断永远归人；</li><li>先人工跑通再逐步自动化，每 10 篇复盘一次流程本身。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>搭流水线的目标不是把写作变成工厂流水活，而是<strong>把可重复的部分全部固化，把创造力集中到选题和观点上</strong>。当&quot;从想法到发布&quot;变成一条有模板、有清单、有节奏的通道，更新不再依赖某天的状态和意志——这也是工程师做内容的天然优势：我们最擅长的就是把手工活变成系统。</p>',33)])])}const g=i(r,[["render",n]]);export{u as __pageData,g as default};
